    DFF dff5 (.d(d[5]), .clk(clk), .q(q_int[5]));
    DFF dff6 (.d(d[6]), .clk(clk), .q(q_int[6]));
    DFF dff7 (.d(d[7]), .clk(clk), .q(q_int[7]));

    // Assign the output
    assign q = q_int;

