// State Transition Table for TopModule
// State | Next state in=0, Next state in=1 | Output
// A     | A, B                             | 0
// B     | C, B                             | 0
// C     | A, D                             | 0
// D     | C, B                             | 1

module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000
    // Derive next_state and out based on state and in

    // Output logic: out is 1 only when current state is D
    assign out = (state == 4'b1000) ? 1 : 0;

    // Next state logic
    // For each state, determine next_state based on in
    // in=0: next_state is the first value, in=1: next_state is the second value

    // State A (0001)
    // in=0 -> A (0001), in=1 -> B (0010)
    // next_state = (in ? 4'b0010 : 4'b0001)

    // State B (0010)
    // in=0 -> C (0100), in=1 -> B (0010)
    // next_state = (in ? 4'b0010 : 4'b0100)

    // State C (0100)
    // in=0 -> A (0001), in=1 -> D (1000)
    // next_state = (in ? 4'b1000 : 4'b0001)

    // State D (1000)
    // in=0 -> C (0100), in=1 -> B (0010)
    // next_state = (in ? 4'b0010 : 4'b0100)

    // Combine all cases using a case statement
    always @(*) begin
        case (state)
            4'b0001: next_state = (in) ? 4'b0010 : 4'b0001; // A
            4'b0010: next_state = (in) ? 4'b0010 : 4'b0100; // B
            4'b0100: next_state = (in) ? 4'b1000 : 4'b0001; // C
            4'b1000: next_state = (in) ? 4'b0010 : 4'b0100; // D
            default: next_state = 4'b0000;
        endcase
    end

endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for input values 2, 7, 15
    // Binary representations:
    // 2: 0010 -> a=0, b=0, c=1, d=0
    // 7: 0111 -> a=0, b=1, c=1, d=1
    // 15: 1111 -> a=1, b=1, c=1, d=1

    // SOP expression: (a' b' c d') + (a' b c d) + (a b c d)
    assign out_sop = (!a & !b & c & !d) | (!a & b & c & d) | (a & b & c & d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 0 for input values 0, 1, 4, 5, 6, 9, 10, 13, 14
    // Binary representations:
    // 0: 0000
    // 1: 0001
    // 4: 0100
    // 5: 0101
    // 6: 0110
    // 9: 1001
    // 10: 1010
    // 13: 1101
    // 14: 1110

    // POS expression: (a + b + c' + d') * (a + b + c' + d) * (a + b' + c + d') * (a + b' + c + d) * (a + b' + c' + d) * (a' + b + c + d') * (a' + b + c + d) * (a' + b + c' + d) * (a' + b' + c + d)
    assign out_pos = 
        (a | b | !c | !d) &
        (a | b | !c | d) &
        (a | !b | c | !d) &
        (a | !b | c | d) &
        (a | !b | !c | d) &
        (!a | b | c | !d) &
        (!a | b | c | d) &
        (!a | b | !c | d) &
        (!a | !b | c | d);

endmodule

