module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);

    // Current state of the game
    reg [255:0] current_q;

    // Next state of the game
    reg [255:0] next_q;

    // Local variables for neighbor count
    reg [7:0] neighbor_count;

    // Determine the number of neighbors for each cell
    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            // Compute next state
            for (integer i = 0; i < 256; i = i + 1) begin
                // Calculate the coordinates
                integer row = i / 16;
                integer col = i % 16;

                // Initialize neighbor count
                neighbor_count = 8'd0;

                // Check all 8 neighbors
                for (integer dr = -1; dr <= 1; dr = dr + 1) begin
                    for (integer dc = -1; dc <= 1; dc = dc + 1) begin
                        if (dr == 0 && dc == 0) continue; // Skip current cell

                        integer n_row = (row + dr) % 16;
                        integer n_col = (col + dc) % 16;

                        integer n_index = n_row * 16 + n_col;
                        neighbor_count += current_q[n_index];
                    end
                end

                // Apply Conway's Game of Life rules
                if (neighbor_count < 2) begin
                    next_q[i] = 1'b0;
                end else if (neighbor_count == 2) begin
                    next_q[i] = current_q[i];
                end else if (neighbor_count == 3) begin
                    next_q[i] = 1'b1;
                end else begin
                    next_q[i] = 1'b0;
                end
            end
            current_q <= next_q;
        end
    end

    // Output the current state
