// State Transition Table for TopModule

// States:
// S0: walk_left
// S1: walk_right
// S2: falling (aaah)
// S3: digging

// Inputs: clk, areset, bump_left, bump_right, ground, dig
// Outputs: walk_left, walk_right, aaah, digging

// State | bump_left | bump_right | ground | dig | Next State | walk_left | walk_right | aaah | digging
// S0    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S0    | 1        | 0         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 0        | 1         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 1        | 1         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S0    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S1    | 0        | 1         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S1    | 1        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S1    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S1    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S2    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S2    | 0        | 0         | 1     | 1  | S2         | 0         | 0          | 1    | 1
// S2    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S2    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S3    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S3    | 0        | 0         | 1     | 1  | S3         | 0         | 0          | 0    | 1
// S3    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S3    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 0

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    typedef enum reg [1:0] {
        S0 = 2'b00, // walk_left
        S1 = 2'b01, // walk_right
        S2 = 2'b10, // falling
        S3 = 2'b11  // digging
    } state_t;

    state_t current_state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= S0;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
        end else begin
            current_state <= next_state;
            walk_left <= (current_state == S0) ? 1 : (current_state == S1) ? 0 : (current_state == S2 || current_state == S3) ? 0 : walk_left;
            walk_right <= (current_state == S0) ? 0 : (current_state == S1) ? 1 : (current_state == S2 || current_state == S3) ? 0 : walk_right;
            aaah <= (current_state == S2) ? 1 : 0;
            digging <= (current_state == S3) ? 1 : 0;
        end
    end

    always @(*) begin
        next_state = current_state;
        case (current_state)
            S0: begin
                if (ground) begin
                    if (dig) next_state = S3;
                    else if (bump_left || bump_right) next_state = S1;
                    else if (!ground) next_state = S2;
                end
            end
            S1: begin
                if (ground) begin
                    if (dig) next_state = S3;
                    else if (bump_left || bump_right) next_state = S0;
                    else if (!ground) next_state = S2;
                end
            end
            S2: begin
                if (ground) next_state = S0;
            end
            S3: begin
                if (!ground) next_state = S2;
                else if (dig) next_state = S3;
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 - below s[0], 1 - between s[1] and s[0], 2 - between s[2] and s[1], 3 - above s[2]
    reg [1:0] current_state;
    reg [1:0] previous_state;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= 2'b00; // Reset to state 0 (below s[0])
            previous_state <= 2'b00;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        current_state <= 2'b11; // Above s[2]
                    end else begin
                        current_state <= 2'b10; // Between s[2] and s[1]
                    end
                end else begin
                    current_state <= 2'b01; // Between s[1] and s[0]
                end
            end else begin
                current_state <= 2'b00; // Below s[0]
            end

            // Determine previous state (used for dfr logic)
            previous_state <= current_state;

            // Output logic based on current state
            case (current_state)
                2'b11: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2'b10: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b01: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b00: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase

            // Check if previous level was lower than current level (dfr condition)
            if (previous_state < current_state) begin
                dfr <= 1'b1;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1 && ground == 0) begin
                next_state = FALLING;
                aaah <= 1;
                digging <= 0;
            end else if (current_state == FALLING && ground == 1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1 - prev_direction;
                aaah <= 0;
                digging <= 0;
            end else if (dig == 1 && current_state == WALK_LEFT && ground == 1) begin
                next_state = DIGGING;
                digging <= 1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (dig == 1 && current_state == WALK_RIGHT && ground == 1) begin
                next_state = DIGGING;
                digging <= 1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING && ground == 0) begin
                next_state = FALLING;
                aaah <= 1;
                digging <= 0;
            end else if (current_state == DIGGING && ground == 1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1 - prev_direction;
                aaah <= 0;
                digging <= 0;
            end else if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                if (bump_left) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                end
            end

            // Update state and outputs
            current_state <= next_state;

            if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                walk_left <= (current_state == WALK_LEFT);
                walk_right <= (current_state == WALK_RIGHT);
                aaah <= 1'b0;
                digging <= 1'b0;
            end else if (current_state == FALLING) begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == DIGGING) begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
                aaah <= 1'b0;
                digging <= 1'b1;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'd0;
            prev_s <= 3'd0;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            // Determine current water level
            if (s[2]) begin
                // Above s[2]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
                state <= 2'd3;
            end else if (s[1]) begin
                // Between s[2] and s[1]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= 1'b0;
                state <= 2'd2;
            end else if (s[0]) begin
                // Between s[1] and s[0]
                fr2 <= 1'b0;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
                state <= 2'd1;
            end else begin
                // Below s[0]
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b1;
                state <= 2'd0;
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state based on current state and inputs
            case (current_state)
                WALK_LEFT: begin
                    // Check if falling (ground is 0)
                    if (!ground) begin
                        next_state = FALLING;
                        prev_direction <= 1'b1;
                    end else if (dig) begin
                        next_state = DIGGING;
                    end else if (bump_right) begin
                        next_state = WALK_RIGHT;
                    end else begin
                        next_state = WALK_LEFT;
                    end
                end

                WALK_RIGHT: begin
                    if (!ground) begin
                        next_state = FALLING;
                        prev_direction <= 1'b0;
                    end else if (dig) begin
                        next_state = DIGGING;
                    end else if (bump_left) begin
                        next_state = WALK_LEFT;
                    end else begin
                        next_state = WALK_RIGHT;
                    end
                end

                FALLING: begin
                    if (ground) begin
                        // Resume walking in previous direction
                        next_state = (prev_direction == 1'b1) ? WALK_LEFT : WALK_RIGHT;
                    end else begin
                        next_state = FALLING;
                    end
                end

                DIGGING: begin
                    if (!ground) begin
                        // Stop digging, start falling
                        next_state = FALLING;
                    end else if (dig) begin
                        next_state = DIGGING;
                    end else begin
                        next_state = (prev_direction == 1'b1) ? WALK_LEFT : WALK_RIGHT;
                    end
                end
            endcase

            current_state <= next_state;
        end
    end

    // Output logic
    always @(posedge clk) begin
        if (current_state == FALLING) begin
            aaah <= 1'b1;
            digging <= 1'b0;
        end else if (current_state == DIGGING) begin
            aaah <= 1'b0;
            digging <= 1'b1;
        end else begin
            aaah <= 1'b0;
            digging <= 1'b0;
        end

        if (current_state == WALK_LEFT) begin
            walk_left <= 1'b1;
            walk_right <= 1'b0;
        end else if (current_state == WALK_RIGHT) begin
            walk_left <= 1'b0;
            walk_right <= 1'b1;
        end
    end

endmodule

// Truth Table/State-Transition Table for TopModule
//
// Inputs:
// clk - clock
// reset - active-high synchronous reset
// s[2:0] - 3-bit sensor input (s[2] is highest, s[0] is lowest)
//
// Outputs:
// fr2 - nominal flow rate input (fr2)
// fr1 - nominal flow rate input (fr1)
// fr0 - nominal flow rate input (fr0)
// dfr - supplemental flow valve (dfr)
//
// State: Based on the sensor input (s) and previous sensor state
//
// State Transitions:
// When reset is asserted, all outputs are set to 1 (fr2, fr1, fr0, dfr = 1)
// When s[2] is asserted (water level above s[2]), all flow rates are 0 (fr2, fr1, fr0 = 0, dfr = 0)
// When s[1] and s[0] are asserted (water level between s[2] and s[1]), fr0 = 1, others = 0, dfr = 0
// When s[0] is asserted (water level between s[1] and s[0]), fr0 = 1, fr1 = 1, dfr = 0
// When no sensors are asserted (water level below s[0]), fr0 = 1, fr1 = 1, fr2 = 1, dfr = 0
// If the sensor change indicates that the previous level was lower than the current level, dfr = 1

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State variables
    reg [2:0] prev_s;

    always @(posedge clk) begin
        if (reset) begin
            // Reset state: no sensors asserted, all outputs high
            fr2 <= 1;
            fr1 <= 1;
            fr0 <= 1;
            dfr <= 1;
            prev_s <= 3'b000;
        end else begin
            // Determine current water level based on s
            if (s[2]) begin
                // Water level above s[2]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
                prev_s <= s;
            end else if (s[1] && !s[0]) begin
                // Water level between s[2] and s[1]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= 1'b0;
                prev_s <= s;
            end else if (s[0]) begin
                // Water level between s[1] and s[0]
                fr2 <= 1'b0;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
                prev_s <= s;
            end else begin
                // Water level below s[0]
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
                prev_s <= s;
            end

            // Check if the previous level was lower than the current level
            if (prev_s < s) begin
                dfr <= 1'b1;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 - below s[0], 1 - between s[1] and s[0], 2 - between s[2] and s[1], 3 - above s[2]
    reg [1:0] current_state;
    reg [1:0] previous_state;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= 2'b00; // Reset to state 0 (below s[0])
            previous_state <= 2'b00;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        current_state <= 2'b11; // Above s[2]
                    end else begin
                        current_state <= 2'b10; // Between s[2] and s[1]
                    end
                end else begin
                    current_state <= 2'b01; // Between s[1] and s[0]
                end
            end else begin
                current_state <= 2'b00; // Below s[0]
            end

            // Determine previous state (for detecting level increase)
            previous_state <= current_state;

            // Output logic based on current state
            case (current_state)
                2'b11: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2'b10: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b01: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b00: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase

            // Check if previous level was lower than current level (state increased)
            if (previous_state < current_state) begin
                dfr <= 1'b1;
            end
        end
    end

endmodule

// State Transition Table for TopModule

// States:
// S0: walk_left
// S1: walk_right
// S2: falling (aaah)
// S3: digging

// Inputs: clk, areset, bump_left, bump_right, ground, dig
// Outputs: walk_left, walk_right, aaah, digging

// State | bump_left | bump_right | ground | dig | Next State | walk_left | walk_right | aaah | digging
// S0    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S0    | 1        | 0         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 0        | 1         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 1        | 1         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S0    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S1    | 0        | 1         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S1    | 1        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S1    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S1    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S2    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S2    | 0        | 0         | 1     | 1  | S2         | 0         | 0          | 1    | 1
// S2    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S2    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S3    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S3    | 0        | 0         | 1     | 1  | S3         | 0         | 0          | 0    | 1
// S3    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S3    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 0

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    typedef enum reg [1:0] {
        S0 = 2'b00, // walk_left
        S1 = 2'b01, // walk_right
        S2 = 2'b10, // falling
        S3 = 2'b11  // digging
    } state_t;

    state_t current_state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= S0;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
        end else begin
            current_state <= next_state;
            walk_left <= (current_state == S0) ? 1 : (current_state == S1) ? 0 : (current_state == S2 || current_state == S3) ? 0 : walk_left;
            walk_right <= (current_state == S0) ? 0 : (current_state == S1) ? 1 : (current_state == S2 || current_state == S3) ? 0 : walk_right;
            aaah <= (current_state == S2) ? 1 : 0;
            digging <= (current_state == S3) ? 1 : 0;
        end
    end

    always @(*) begin
        next_state = current_state;
        case (current_state)
            S0: begin
                if (ground) begin
                    if (dig) next_state = S3;
                    else if (bump_left || bump_right) next_state = S1;
                    else if (!ground) next_state = S2;
                end
            end
            S1: begin
                if (ground) begin
                    if (dig) next_state = S3;
                    else if (bump_left || bump_right) next_state = S0;
                    else if (!ground) next_state = S2;
                end
            end
            S2: begin
                if (ground) next_state = S0;
            end
            S3: begin
                if (!ground) next_state = S2;
                else if (dig) next_state = S3;
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (ground == 1'b0 && prev_ground == 1'b1) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (ground == 1'b1 && prev_ground == 1'b0) begin
                // Ground reappeared, resume walking
                if (was_falling) begin
                    next_state = WALK_LEFT;
                    walk_left <= prev_direction;
                    walk_right <= ~prev_direction;
                    aaah <= 1'b0;
                end
            end else if (dig) begin
                if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                    if (ground == 1'b1 && prev_ground == 1'b1) begin
                        next_state = DIGGING;
                        digging <= 1'b1;
                        walk_left <= 1'b0;
                        walk_right <= 1'b0;
                    end
                end
            end else if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                // Check for bump
                if (bump_left) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                end
            end

            // Update state and outputs
            current_state <= next_state;

            // Update outputs based on state
            case (current_state)
                WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                FALLING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    digging <= 1'b0;
                end
                DIGGING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end
            endcase
        end
    end

endmodule
